#include <stdio.h>
#include <stdlib.h>

int miller_rabin(unsigned long n) {
    if (n < 2) return 0;
    if (n == 2) return 1;
    if (n % 2 == 0) return 0;
    unsigned long s = 0, d = n - 1;
    while (d % 2 == 0) {
        s++;
        d /= 2;
    }
    for (unsigned long i = 0; i < 5; i++) {
        unsigned long a = (unsigned long)rand() % (n - 2) + 2;
        unsigned long x = 1;
        for (unsigned long j = 0; j < s; j++) {
            x = (x * x) % n;
            if (x == 1 || x == n - 1) break;
        }
        if (x != n - 1) return 0;
    }
    return 1;
}

int main(int argc, char **argv) {
    if (argc < 2) {
        printf("NO_INPUT\n");
        return 0;
    }
    char *endptr;
    unsigned long n = strtoll(argv[1], &endptr, 10);
    if (*endptr != '\0') {
        printf("BAD_INPUT\n");
        return 0;
    }
    if (n > 4294967295UL) {
        printf("OUT_OF_RANGE\n");
        return 0;
    }
    if (miller_rabin(n)) {
        printf("PRIME\n");
    } else {
        printf("NOT_PRIME\n");
    }
    return 0;
}
